# The grids store 8 (uint64) or 4 (uint32) byte-sized values per entry; unpack once so
# dequantization is a plain gather.
IQ2XXS_GRID_U8 = IQ2XXS_GRID.view(np.uint8).reshape(-1, 8)
IQ2XS_GRID_U8  = IQ2XS_GRID.view(np.uint8).reshape(-1, 8)
IQ2S_GRID_U8   = IQ2S_GRID.view(np.uint8).reshape(-1, 8)
IQ3XXS_GRID_U8 = IQ3XXS_GRID.view(np.uint8).reshape(-1, 4)
IQ3S_GRID_U8   = IQ3S_GRID.view(np.uint8).reshape(-1, 4)

# Two different sign conventions in ggml:
#  * IQ2_XXS / IQ2_XS / IQ3_XXS index the ksigns_iq2xs table with a 7-bit code -> SIGNS
#  * IQ2_S / IQ3_S use the stored sign BYTE directly as a bitmask          -> SIGNS_BYTE
# In both cases bit j (via kmask_iq2xs) means "negate element j".
SIGNS = np.where((KSIGNS_IQ2XS[:, None] & KMASK_IQ2XS[None, :]) != 0, -1.0, 1.0).astype(np.float32)
SIGNS_BYTE = np.where((np.arange(256, dtype=np.uint16)[:, None] & KMASK_IQ2XS[None, :].astype(np.uint16)) != 0,
                      -1.0, 1.0).astype(np.float32)
